function D.new(class, props, kids)
	local o = Instance.new(class)
	local parent
	if props then
		for k, v in pairs(props) do
			if k == "Parent" then parent = v else o[k] = v end
		end
	end
	if kids then
		for _, c in ipairs(kids) do c.Parent = o end
	end
	if parent then o.Parent = parent end
	return o
end
local new = D.new

function D.corner(p, r)
	return new("UICorner", {CornerRadius = UDim.new(0, r), Parent = p})
end

function D.stroke(p, tr, rim)
	local s = new("UIStroke", {Color = T.ink, Transparency = tr or 0.92, Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border})
	pcall(function() s.BorderStrokePosition = Enum.BorderStrokePosition.Inner end)
	if rim and S.ui_rim ~= false and not T.light then
		new("UIGradient", {Rotation = 90, Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0),
			NumberSequenceKeypoint.new(0.18, 0.45),
			NumberSequenceKeypoint.new(1, 0.72),
		}), Parent = s})
	end
	s.Parent = p
	return s
end

function D.pad(p, t, r, b, l)
