			local ok, f = pcall(function() return LP:IsFriendsWith(p.UserId) end)
			if ok and f and D.alive then D.notify(p.DisplayName, "Your friend joined", {icon = "heart", dur = 4}) end
		end)
	end
end)
D.on(Players.PlayerRemoving, function(p)
