		Content = "Every option goes back to default. Saved configs, positions and pictures are deleted.",
		Icon = "triangle-alert",
		Buttons = {{Name = "Cancel"}, {Name = "Reset", Style = "Primary", Callback = function() D.resetEverything() end}},
	})
end
