function Window:SetBackground(o)
	o = type(o) == "string" and {Image = o} or o or {}
	if o.Opacity then D.set("bg_opacity", math.clamp(math.floor(o.Opacity * 100 + 0.5), 0, 100)) end
	if o.Darken then D.set("bg_dark", math.clamp(math.floor(o.Darken * 100 + 0.5), 0, 100)) end
	if o.Fit then D.set("bg_fit", o.Fit) end
	if o.Image then
		task.spawn(function()
			local img, asset = o.Image
			if string.find(img, "^https?://") then
				asset = D.fetchImage(img, "background")
			elseif string.match(img, "^%d+$") then
				asset = "rbxassetid://" .. img
			else
				asset = img
			end
			if asset then
				D.bgAsset = asset
				D.set("bg_on", true)
				D.applyBackground()
			end
		end)
	elseif o.Enabled ~= nil then
		D.set("bg_on", o.Enabled == true)
	end
end

local function checkKey(ks, key)
	key = string.gsub(string.gsub(tostring(key or ""), "^%s+", ""), "%s+$", "")
	if key == "" then return false end
	if type(ks.Check) == "function" then
		local ok, r = pcall(ks.Check, key)
		return ok and r == true
	end
	local keys = ks.Keys or ks.Key
	if type(keys) == "string" then keys = {keys} end
	for _, k in ipairs(type(keys) == "table" and keys or {}) do
		if tostring(k) == key then return true end
	end
	return false
end

local function runKeySystem(ks, done)
	local path = DIR .. "/key.txt"
	if ks.SaveKey ~= false and isfile and readfile then
		local ok, saved = pcall(function() return isfile(path) and readfile(path) end)
		if ok and type(saved) == "string" and checkKey(ks, saved) then
			done()
			return
		end
	end
	for k, v in pairs(D.DEF_OVERRIDES or {}) do S[k] = D.clone(v) end
	D.applyTheme()
	D.applyMetrics()
	local buttons = {}
	if ks.Link then
		buttons[#buttons + 1] = {Name = "Get Key", Keep = true, Callback = function()
			if setclipboard then pcall(setclipboard, tostring(ks.Link)) end
			D.notify(ks.Title or "Key", "Link copied.", {icon = "copy", dur = 2.5})
		end}
	end
	buttons[#buttons + 1] = {Name = "Continue", Style = "Primary", Callback = function(key)
		if ks.SaveKey ~= false and writefile then
			D.ensureDir(DIR)
			pcall(writefile, path, string.gsub(string.gsub(tostring(key or ""), "^%s+", ""), "%s+$", ""))
		end
		done()
	end}
	D.openDialog({
		Title = ks.Title or ((D.CONFIG.Title or "arvn") .. " Key"),
		Content = ks.Note or ks.Content,
		Icon = "key-round",
		Input = {Placeholder = ks.Placeholder or "Enter key"},
		Dismissable = false,
		Validate = function(key)
			if checkKey(ks, key) then return true end
			return false, ks.Wrong or "That key is not valid."
		end,
		Buttons = buttons,
	})
end

function API:CreateWindow(o)
	o = o or {}
	if D.windowObj then return D.windowObj end
	local cfg = D.CONFIG
	local ov = D.DEF_OVERRIDES or {}
	D.DEF_OVERRIDES = ov
	if type(o.Defaults) == "table" then
		for k, v in pairs(o.Defaults) do
			ov[tostring(k)] = typeof(v) == "Color3" and hex(v) or v
		end
	end
	cfg.Title = o.Title or o.Name or "arvn"
	cfg.Subtitle = o.Subtitle or o.SubTitle
	cfg.Author = o.Author or o.Credits
	cfg.Version = o.Version
	cfg.Logo = o.Logo or o.Icon
	for _, key in ipairs({"Dashboard", "Server", "Tools"}) do
		cfg[key] = (o[key] ~= nil and o[key] ~= false) or nil
	end
	if o.Settings == false then cfg.Settings = false else cfg.Settings = nil end
	cfg.LoadNotification = o.LoadNotification
	local about
	for _, c in ipairs(D.BUILTIN.settings.children) do
		if c.id == "set_interface" then
			for _, col in ipairs(c.page) do
				for _, sec in ipairs(col) do
					if sec.title == "About" then about = sec end
				end
			end
		end
	end
	if about then
		for _, r in ipairs(about.rows) do
			if r.id == "i_author" and not o.Author then r.hidden = true end
			if r.id == "i_version" and not o.Version then r.hidden = true end
		end
		local extra = {}
		for i, c in ipairs(type(o.Credits) == "table" and o.Credits or {}) do
			local name = type(c) == "table" and (c.Name or c[1]) or nil
			local value = type(c) == "table" and (c.Value or c[2]) or tostring(c)
			if name then
				local id = "i_credit_" .. i
				extra[#extra + 1] = {t = "info", id = id, label = tostring(name), desc = "Credits.", value = tostring(value)}
				S[id] = tostring(value)
			end
		end
		for i, r in ipairs(extra) do table.insert(about.rows, 3 + i, r) end
	end
	cfg.MainGroup = o.MainGroup
	if o.Folder then DIR = tostring(o.Folder) end
	cfg.Width = o.Width or (o.Size and (typeof(o.Size) == "Vector2" and o.Size.X or typeof(o.Size) == "UDim2" and o.Size.X.Offset)) or nil
	cfg.Height = o.Height or (o.Size and (typeof(o.Size) == "Vector2" and o.Size.Y or typeof(o.Size) == "UDim2" and o.Size.Y.Offset)) or nil
	cfg.SidebarWidth = o.SidebarWidth
	local G = D.BUILTIN_GROUPS
	local groups = o.Groups or {}
	G.main.group = groups.Main or o.MainGroup or G.main.group
	G.utility.group = groups.Utility or o.UtilityGroup or G.utility.group
	G.settings.group = groups.Settings or o.SettingsGroup or G.settings.group
	local PAGES = {Dashboard = "home", Server = "server", Tools = "tools", Settings = "settings", General = "set_interface", Interface = "set_interface", Appearance = "set_theme", Theme = "set_theme", Overlays = "set_overlays", Profile = "set_personal", Personalize = "set_personal", Sounds = "set_sounds", Configs = "set_configs"}
	local function pageEntry(id)
		if D.BUILTIN[id] then return D.BUILTIN[id] end
		for _, c in ipairs(D.BUILTIN.settings.children) do
			if c.id == id then return c end
		end
	end
	for key, id in pairs(PAGES) do
		local v = key ~= "Theme" and key ~= "Profile" and o[key] or nil
		if v == nil and type(o.Pages) == "table" then v = o.Pages[key] end
		if v == nil and type(o.SettingsPages) == "table" then v = o.SettingsPages[key] end
		local e = pageEntry(id)
		if e then
			e.builtin = true
			if v == false then
				e.hidden = true
			elseif type(v) == "table" then
				if v.Name then e.name = v.Name end
				if v.Icon then e.icon = pickIcon(v.Icon, e.icon) end
			elseif type(v) == "string" then
				e.name = v
			end
		end
	end
	if type(o.Colors) == "table" then API:SetColors(o.Colors) end
	cfg.Resizable = o.Resizable
	cfg.Search = o.Search
	cfg.SubFolder = o.SubFolder
	cfg.WatermarkText = o.WatermarkText
	local ub = o.UIButton
	if ub == nil then ub = o.MobileButton end
	if type(ub) == "table" then
		cfg.UIButton = ub
	elseif ub == false then
		ov.ui_button = false
	end
	if o.Sounds == false then ov.snd_on = false end
	if o.Notifications == false then ov.nt_on = false end
	if type(o.Background) == "table" or type(o.Background) == "string" then
		local bg = type(o.Background) == "string" and {Image = o.Background} or o.Background
		cfg.Background = bg
		ov.bg_on = true
		if bg.Opacity then ov.bg_opacity = math.clamp(math.floor(bg.Opacity * 100 + 0.5), 0, 100) end
		if bg.Darken then ov.bg_dark = math.clamp(math.floor(bg.Darken * 100 + 0.5), 0, 100) end
		if bg.Fit then ov.bg_fit = bg.Fit end
	end
	if o.NotifySide then ov.nt_pos = o.NotifySide end
	if o.MenuKey and D.validKey("ui_menukey", o.MenuKey) then ov.ui_menukey = o.MenuKey end
	if o.Theme then
		ov.ui_theme = D.themeName(o.Theme)
		local p = D.PALETTES[ov.ui_theme]
		if p and p.accent and not o.Accent then ov.ui_accent = "#" .. string.sub(p.accent, 1, 6) .. "FF" end
	end
	if o.Accent then ov.ui_accent = hex(o.Accent) end
	if o.OpenOnLoad == false then ov.ui_openload = false end
	if o.Watermark == false then ov.ov_wm = false end
	if o.Keybinds == false then ov.ov_kb = false end
	if o.Keystrokes ~= nil then ov.ov_ks = o.Keystrokes == true end
	if o.ToggleStyle then ov.ui_toggle = o.ToggleStyle end
	if o.Font then ov.ui_font = o.Font end
	if o.Scale then ov.ui_scale = o.Scale end
	if o.Particles then ov.fx_style = o.Particles end
	if o.Blur ~= nil then ov.ui_blur = o.Blur == true end
	if o.ShowErrors ~= nil then API.ShowErrors = o.ShowErrors end
	local win = setmetatable({Flags = API.Flags, API = API}, Window)
	D.windowObj = win
	cfg.KeySystem = type(o.KeySystem) == "table" and o.KeySystem or nil
	task.defer(function()
		if not D.alive then return end
		if cfg.KeySystem then
			runKeySystem(cfg.KeySystem, function()
				if D.alive then D.start() end
			end)
		else
			D.start()
		end
	end)
	return win
end
API.Window = API.CreateWindow
end
return D.API
end)()

-- ===== Chilli Library -> arvn UI adapter =====
-- Keeps the Chilli API the script already calls (CreateWindow / CreateTab / CreateSection /
-- CreateToggle / CreateSlider / ...), but every element is drawn by arvn.
local TweenAccent = Color3.fromRGB(55, 235, 120)

local Library = { ManualQuickDefaults = nil }
local Window = { _destroyed = false }
local states = {}
local arvnWindow, arvnGroup

local TabIcons = {
    Stealer = "hand",
    Helper = "wrench",
    Player = "user",
    ESP = "eye",
    Misc = "sliders-horizontal",
    Server = "server",
    ["AP&TP"] = "map-pin",
}

local function keyName(k)
    if typeof(k) == "EnumItem" then return k.Name end
    if type(k) == "string" and k ~= "" then return (k:gsub("^Enum%.KeyCode%.", "")) end
    return nil
end

local function unwrap(v)
    if type(v) == "table" and rawget(v, "_el") then return v._el end
    return v
end

-- default keybinds that the original hub shipped with ("Tab > Section > Name")
local function defaultKey(path)
    local qd = Library.ManualQuickDefaults
    local kb = type(qd) == "table" and qd.Keybinds
    if type(kb) == "table" and type(kb[path]) == "string" then return kb[path] end
    return nil
end

local function condition(o)
    if o.ShowWhen ~= nil then return unwrap(o.ShowWhen) end
    local parent = o.SubOf
    if type(parent) == "table" and rawget(parent, "_kind") == "toggle" then
        return unwrap(parent) -- sub-options only show while their parent toggle is on
    end
    return nil
end

-- Chilli applied every element's starting value through its callback, so do the same
-- (deferred, in creation order, once the rest of the script has finished setting up).
local function fireInitial(el, callback)
    if type(callback) ~= "function" then return end
    task.defer(function()
        if Window._destroyed then return end
        local ok, value = pcall(function() return el:Get() end)
        if not ok then return end
        local ran, err = pcall(callback, value)
        if not ran then warn(tostring(err)) end
    end)
end

local function proxy(el, kind, callback)
    if callback ~= nil then fireInitial(el, callback) end
    local p = { _el = el, _kind = kind }
    function p:Get() return el:Get() end
    p.GetValue = p.Get
    function p:Set(value, fire)
        if kind == "slider" then value = tonumber(value) or value end
        el:Set(value, fire == false)
        return self
    end
    function p:SetRange(lo, hi)
        pcall(function() el:SetRange(lo, hi) end)
        return self
    end
    function p:SetOptions(list, default)
        pcall(function() el:SetValues(list or {}, true) end)
        if default ~= nil then pcall(function() el:Set(default, true) end) end
        return self
    end
    function p:SetVisible(v) pcall(function() el:SetVisible(v ~= false) end) return self end
    function p:SetText(t) pcall(function() el:SetContent(t) end) return self end
    return setmetatable(p, {
        __index = function(t, k)
            if k == "Value" then return el:Get() end
            local f = el[k]
            if type(f) == "function" then
                return function(_, ...) return f(el, ...) end
            end
        end,
    })
end

local function makeSection(arvnTab, tabName, cfg)
    local sectionName = tostring(cfg.Name or "Section")
    local sec = arvnTab:Section({ Name = sectionName })
    local S = {}

    local function path(name) return tabName .. " > " .. sectionName .. " > " .. tostring(name) end

    function S:CreateToggle(o)
        local name = tostring(o.Name or "Toggle")
        local key = keyName(o.Keybind) or defaultKey(path(name))
        local el = sec:Toggle({
            Name = name,
            Default = o.Default == true,
            Description = o.Note,
            Keybind = key,
            ShowWhen = condition(o),
            Callback = o.Callback,
        })
        return proxy(el, "toggle", o.Callback)
    end

    function S:CreateSlider(o)
        local name = tostring(o.DisplayName or o.Name or "Slider")
        local el = sec:Slider({
            Name = name,
            Min = o.Min or 0,
            Max = o.Max or 100,
            Default = o.Default,
            Step = o.Increment,
            Suffix = o.Unit,
            Description = o.Note,
            ShowWhen = condition(o),
            Callback = o.Callback,
        })
        return proxy(el, "slider", o.Callback)
    end

    function S:CreateButton(o)
        local name = tostring(o.Name or "Button")
        local key = keyName(o.Keybind) or defaultKey(path(name))
        local el = sec:Button({
            Name = name,
            Description = o.Note,
            Confirm = o.ConfirmText ~= nil or nil,
            Keybind = key,
            ShowWhen = condition(o),
            Callback = o.Callback,
        })
        return proxy(el, "button")
    end

    function S:CreateDropdown(o)
        local el = sec:Dropdown({
            Name = tostring(o.Name or "Dropdown"),
            Options = o.Options or {},
            Default = o.Default,
            Description = o.Note,
            ShowWhen = condition(o),
            Callback = o.Callback,
        })
        return proxy(el, "dropdown", o.Callback)
    end

    function S:CreateMultiDropdown(o)
        local el = sec:Dropdown({
            Name = tostring(o.Name or "Dropdown"),
            Options = o.Options or {},
            Default = o.Default or {},
            Multi = true,
            Description = o.Note,
            ShowWhen = condition(o),
            Callback = o.Callback,
        })
        return proxy(el, "multidropdown", o.Callback)
    end

    function S:CreateInput(o)
        local el = sec:Input({
            Name = tostring(o.Name or "Input"),
            Default = tostring(o.Default or ""),
            Placeholder = o.Placeholder,
            MaxLength = o.MaxLength,
            Description = o.Note,
            ShowWhen = condition(o),
            Callback = o.Callback,
        })
        return proxy(el, "input", o.Callback)
    end

    function S:CreateText(o)
        local el = sec:Paragraph({
            Title = tostring(o.Name or ""),
            Body = tostring(o.Text or ""),
        })
        return proxy(el, "text")
    end

    S.CreateLabel = S.CreateText
    return S
end

local function makeTab(cfg)
    if type(cfg) == "string" then cfg = { Name = cfg } end
    cfg = cfg or {}
    local tabName = tostring(cfg.Name or "Tab")
    local arvnTab = arvnGroup:Tab({ Name = tabName, Icon = TabIcons[tabName] or "package" })
    local T = {}
    function T:CreateSection(sectionCfg)
        if type(sectionCfg) == "string" then sectionCfg = { Name = sectionCfg } end
        return makeSection(arvnTab, tabName, sectionCfg or {})
    end
    return T
end

local function newState(default)
    local value = default
    local st = {}
    function st:Get() return value end
    function st:Set(v) value = v return self end
    return st
end

function Window:CreateTab(cfg) return makeTab(cfg) end

-- the original hub had a hidden "Main" tab; nothing is ever placed in it
function Window:GetDefaultTab()
    local stub = {}
    function stub:CreateSection()
        local s = {}
        return setmetatable(s, { __index = function() return function() return proxy({
            Get = function() end, Set = function() end,
        }, "stub") end end })
    end
    return stub
end

function Window:CreateState(cfg)
    cfg = cfg or {}
    local st = newState(cfg.Default)
    if cfg.Name then states[cfg.Name] = st end
    return st
end

function Window:GetState(name)
    if name == nil then return nil end
    if not states[name] then states[name] = newState({}) end
    return states[name]
end

function Window:Open() Arvn:Toggle(true) end
function Window:Close() Arvn:Toggle(false) end
function Window:Destroy() pcall(function() Arvn:Eject() end) end

function Library:CreateWindow(cfg)
    cfg = cfg or {}
    local title = tostring(cfg.Name or "Chilli Hub")
    arvnWindow = Arvn:CreateWindow({
        Title = title,
        Subtitle = "Welcome to " .. title .. " • Have fun",
        Author = title,
        Theme = "Dark",
        Accent = TweenAccent,
        MenuKey = "RightShift",
        LoadNotification = title .. " loaded. Press RightShift to open the menu.",
    })
    arvnGroup = arvnWindow:Group(title)
    pcall(function() Arvn:OnEject(function() Window._destroyed = true end) end)
    return Window
end

function Library.Notify(title, text, duration)
    pcall(function()
        Arvn:Notify({
            Title = tostring(title or "Notification"),
            Content = tostring(text or ""),
            Duration = tonumber(duration) or 4,
        })
    end)
end

function Library:Finalize() return true end

return Library
end)()

